&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types d&#39;alchimiste&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_dalchimiste_0&quot; href=&quot;#Les_arch&#233;types_dalchimiste_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste-Des-Marais-(Alchimiste).html&quot; title=&quot;Alchimiste des marais&quot;&gt;Alchimiste des marais&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Grippli-(Race).html&quot; title=&quot;Les gripplis&quot;&gt;Grippli&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste-Interne-(Alchimiste).html&quot; title=&quot;Alchimiste interne&quot;&gt;Alchimiste interne&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animorphe-(Alchimiste).html&quot; title=&quot;Animorphe&quot;&gt;Animorphe&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artificier-Des-Profondeurs-(Alchimiste).html&quot; title=&quot;Artificier des profondeurs&quot;&gt;Artificier des profondeurs&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Svirfneblin-(Race).html&quot; title=&quot;Les svirfneblins&quot;&gt;Svirfneblin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brasseur-D&#233;pines-(Alchimiste).html&quot; title=&quot;Brasseur d&amp;#39;&#233;pines&quot;&gt;Brasseur d&#39;&#233;pines&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chercheur-Dœnopion-(Alchimiste).html&quot; title=&quot;Chercheur visionnaire&quot;&gt;Chercheur visionnaire&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Enrag&#233;-(Alchimiste).html&quot; title=&quot;Chimiste enrag&#233;&quot;&gt;Chimiste enrag&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Inspir&#233;-(Alchimiste).html&quot; title=&quot;Chimiste inspir&#233;&quot;&gt;Chimiste inspir&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Spirituel-(Alchimiste).html&quot; title=&quot;Chimiste spirituel&quot;&gt;Chimiste spirituel&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chirurgien-(Alchimiste).html&quot; title=&quot;Chirurgien&quot;&gt;Chirurgien&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collectionneur-(Alchimiste).html&quot; title=&quot;Collectionneur&quot;&gt;Collectionneur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ectochimiste-(Alchimiste).html&quot; title=&quot;Ectochimiste&quot;&gt;Ectochimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Explorateur-De-Cryptes-(Alchimiste).html&quot; title=&quot;Explorateur de cryptes&quot;&gt;Explorateur de cryptes&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grenadier-(Alchimiste).html&quot; title=&quot;Grenadier&quot;&gt;Grenadier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homonculiste-(Alchimiste).html&quot; title=&quot;Homonculiste &quot;&gt;Homonculiste&lt;/a&gt; (FF)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interrogateur-(Alchimiste).html&quot; title=&quot;Interrogateur&quot;&gt;Interrogateur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inventeur-Alchimiste-(Alchimiste).html&quot; title=&quot;Inventeur alchimiste&quot;&gt;Inventeur alchimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Clones-(Alchimiste).html&quot; title=&quot;Ma&#238;tre des clones&quot;&gt;Ma&#238;tre des clones&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maraudeur-Ail&#233;-(Alchimiste).html&quot; title=&quot;Maraudeur ail&#233;&quot;&gt;Maraudeur ail&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-(Alchimiste).html&quot; title=&quot;M&#233;tamorphe&quot;&gt;M&#233;tamorphe&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Peste-(Alchimiste).html&quot; title=&quot;Porte-peste&quot;&gt;Porte-peste&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychonaute-(Alchimiste).html&quot; title=&quot;Psychonaute&quot;&gt;Psychonaute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrobombardier-(Alchimiste).html&quot; title=&quot;Pyrobombardier&quot;&gt;Pyrobombardier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;animateur-(Alchimiste).html&quot; title=&quot;R&#233;animateur&quot;&gt;R&#233;animateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saboteur-(Alchimiste).html&quot; title=&quot;Saboteur&quot;&gt;Saboteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sapeur-Alchimique-(Alchimiste).html&quot; title=&quot;Sapeur alchimique&quot;&gt;Sapeur alchimique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-Alchimique-(Alchimiste).html&quot; title=&quot;Trappeur alchimique&quot;&gt;Trappeur alchimique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vivisectioniste-(Alchimiste).html&quot; title=&quot;Vivisectioniste&quot;&gt;Vivisectioniste&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;b&gt;Source : Ultimate intrigue&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Les Sapeurs alchimique sont entra&#238;n&#233;s &#224; la cr&#233;ation d&#39;explosifs.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Alchimie diminu&#233;e&lt;a class=&quot;headeranchor&quot; id=&quot;Alchimie_diminu&#233;e_0&quot; href=&quot;#Alchimie_diminu&#233;e_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un sapeur alchimiste peut pr&#233;parer un extrait de moins de chaque niveau par rapport &#224; la normale. Si cela r&#233;duit le nombre &#224; 0, il peut pr&#233;parer un extrait de ce niveau uniquement si son intelligence &#233;lev&#233;e lui permet la cr&#233;ation d&#39;extraits suppl&#233;mentaires de ce niveau.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_1&quot; href=&quot;#Comp&#233;tences_de_classe_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un sapeur alchimique ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (ing&#233;nierie) et &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe.&lt;br /&gt;&lt;br /&gt;Cela alt&#232;re les comp&#233;tences de classe de l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bombe de d&#233;molition (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Bombe_de_d&#233;molition_Sur_2&quot; href=&quot;#Bombe_de_d&#233;molition_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, un sapeur alchimique peut cr&#233;er une bombe de d&#233;molition. Cette bombe inflige deux fois plus de d&#233;g&#226;ts qu&#39;une bombe normale, la premi&#232;re moiti&#233; inflige des d&#233;g&#226;ts contondants et per&#231;ants, le seconde des d&#233;g&#226;ts de feu. Cette bombe ignore un nombre de points de solidit&#233; &#233;gaux &#224; 1/2 du niveau de sapeur alchimique (minimum 1). Cela compte comme une comme une aptitude qui modifie la bombe du sapeur alchimique, cela ne se cumule donc pas avec d&#39;autres &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;d&#233;couvertes&lt;/a&gt; qui modifient les bombes. Le sapeur alchimique ne peut pas utiliser sa bombe de d&#233;molition avec la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBESRAPIDES&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombes rapides&lt;/a&gt;. Un sapeur alchimique ne peut se servir d&#39;une utilisation par jour de sa comp&#233;tence de classe bombes pour cr&#233;er une bombe de d&#233;molition. Il peut cr&#233;er une bombe de d&#233;molition suppl&#233;mentaire &#224; partir du niveau 5 et une de plus tous les quatre niveaux apr&#232;s.&lt;br /&gt;&lt;br /&gt;Ce pouvoir modifie &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#BOMBES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;bombes&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bombe &#224; retardement (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Bombe_&#224;_retardement_Sur_3&quot; href=&quot;#Bombe_&#224;_retardement_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un sapeur alchimique gagne la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEARETARDEMENT&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe &#224; retardement&lt;/a&gt; au niveau 1. Il ne peut apprendre les d&#233;couvertes &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#MUTAGENE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;mutag&#232;ne&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#COGNATOGENE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;cognatog&#232;ne&lt;/a&gt; avant le niveau 8.&lt;br /&gt;&lt;br /&gt;Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#MUTAGENES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;mutag&#232;ne&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre ing&#233;nieur (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_ing&#233;nieur_Ext_4&quot; href=&quot;#Ma&#238;tre_ing&#233;nieur_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, un sapeur alchimique ajoute 1/2 de son niveau d&#39;alchimiste &#224; ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (ing&#233;nierie), &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (constructions en pierre) et &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (pi&#232;ges).&lt;br /&gt;&lt;br /&gt;Ce pouvoir remplace la &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#RESISTPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;r&#233;sistance aux poisons&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bombe camoufl&#233;e (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Bombe_camoufl&#233;e_Ext_5&quot; href=&quot;#Bombe_camoufl&#233;e_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, un sapeur alchimique devient capable de cacher ses bombes. Lorsqu&#39;il d&#233;ploie une &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEARETARDEMENT&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe &#224; retardement&lt;/a&gt; ou une mine de proximit&#233; (voir plus bas), le sapeur alchimique peut camoufler la bombe en d&#233;pensant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; complet. Les cr&#233;atures recherchant les pi&#232;ges doivent r&#233;ussir un test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; = 10 + le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de sapeur alchimique + son modificateur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;) pour d&#233;nicher les bombes camoufl&#233;es.&lt;br /&gt;&lt;br /&gt;Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#ALCHIMIERAPIDE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimie rapide&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mine de proximit&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Mine_de_proximit&#233;_Sur_6&quot; href=&quot;#Mine_de_proximit&#233;_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 6, un sapeur alchimique peut d&#233;penser deux utilisations de sa comp&#233;tence de classe bombes (Sur) pour pr&#233;parer un pi&#232;ge sp&#233;cifique appel&#233; une mine de proximit&#233;. Cette bombe sp&#233;ciale reste inactive 1 round apr&#232;s avoir quitt&#233; la possession du sapeur alchimique, apr&#232;s ce d&#233;lai elle s&#39;arme. Lorsqu&#39;une cr&#233;ature entre sur une case contenant une mine de proximit&#233; arm&#233;e, elle explose, causant des d&#233;g&#226;ts de bombe habituels &#224; toutes les cr&#233;atures dans la case (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; = 10 + 1/2 la moiti&#233; du niveau d&#39;alchimiste du sapeur alchimique + son modificateur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de R&#233;flexes&lt;/a&gt; pour r&#233;duire les d&#233;g&#226;ts de moiti&#233;) et des d&#233;g&#226;ts d&#39;&#233;claboussure sur les cases adjacentes &#224; ce carr&#233;. Une mine de proximit&#233; peut &#234;tre d&#233;sarm&#233;e en r&#233;ussissant un test de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; = 10 + 1/2 niveau d&#39;alchimiste du sapeur alchimique + son modificateur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;) ; sinon, elle reste active jusqu&#39;&#224; ce que l&#39;alchimiste pr&#233;pare son prochain lot de bombes quotidiennes.&lt;br /&gt;&lt;br /&gt;Si le sapeur alchimique d&#233;pense quatre utilisations de sa comp&#233;tence de classe bombes, la mine de proximit&#233; fait autant de d&#233;g&#226;ts qu&#39;une bombe de d&#233;molition ; cela ne compte pas comme une utilisation quotidienne de la comp&#233;tence bombe de d&#233;molition. A part la modification de bombe de d&#233;molition, les &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;d&#233;couvertes&lt;/a&gt; qui modifient la mine de proximit&#233; ne sont pas applicables.&lt;br /&gt;&lt;br /&gt;Ce pouvoir remplace la &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#DECOUVERTES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;d&#233;couverte&lt;/a&gt; gagn&#233;e au niveau 6.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;tonation s&#233;lective (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;tonation_s&#233;lective_Sur_7&quot; href=&quot;#D&#233;tonation_s&#233;lective_Sur_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10, lorsqu&#39;un sapeur alchimique place une mine de proximit&#233;, il peut d&#233;signer un nombre d&#39;alli&#233;s &#233;gal &#224; son modificateur d&#39;intelligence, leur permettant de passer en s&#233;curit&#233; par une case &#233;quip&#233;e d&#39;une mine de proximit&#233; arm&#233;e sans la faire d&#233;toner. Si une autre cr&#233;ature active le pi&#232;ge alors qu&#39;un alli&#233; est proche, l&#39;alli&#233; prend tout de m&#234;me les d&#233;g&#226;ts normaux.&lt;br /&gt;&lt;br /&gt;Ce pouvoir remplace l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#RESISTPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;immunit&#233; aux poisons&lt;/a&gt; du niveau 10.
